import re


def entities(doc, scope):
    children_list = scope_nodes(doc, scope)
    objects_node = None
    for node in children_list:
        if node.get("kind") == "list" and ": Objects" in node["title"]:
            objects_node = node
            break

    if objects_node is None:
        return []

    result = []
    for line in objects_node["lines"]:
        match = re.match(r'Object (\d+): (.+)', line)
        if match:
            result.append({"id": match.group(1), "description": match.group(2)})
    return result


def recorded_end(doc, scope):
    children_list = scope_nodes(doc, scope)
    motion_node = None
    events_node = None
    for node in children_list:
        if "Motion log" in node["title"]:
            motion_node = node
        if "Events" in node["title"]:
            events_node = node

    max_frame = -1

    if motion_node and motion_node.get("kind") == "table":
        for _, rd in table_rows(motion_node):
            try:
                fv = rd.get("frame", "")
                if fv:
                    max_frame = max(max_frame, float(fv))
            except (ValueError, TypeError):
                pass

    if events_node and events_node.get("kind") == "list":
        for line in events_node["lines"]:
            m = re.match(r'Frame (\d+):', line)
            if m:
                max_frame = max(max_frame, int(m.group(1)))

    return float(max_frame) if max_frame >= 0 else None


def inputs(doc, scope):
    children_list = scope_nodes(doc, scope)
    events_node = None
    objects_node = None
    for node in children_list:
        if "Events" in node["title"]:
            events_node = node
        if ": Objects" in node["title"]:
            objects_node = node

    result = []
    if events_node is None:
        return result

    obj_info = {}
    if objects_node:
        for line in objects_node["lines"]:
            m = re.match(r'Object (\d+): (.+)', line)
            if m:
                obj_info[m.group(1)] = m.group(2)

    for i, line in enumerate(events_node["lines"]):
        m_enter = re.match(r'Frame (\d+): Object (\d+) \(.+\) enters the scene\.', line)
        m_init = re.match(r'Frame (\d+): Object (\d+) \(.+\) is in view when the video begins\.', line)

        if m_enter:
            oid = m_enter.group(2)
            result.append({
                "id": "enter_" + oid,
                "time": float(m_enter.group(1)),
                "kind": "object_enter",
                "entities": [oid],
                "fields": {"description": obj_info.get(oid, "Object " + oid)},
                "src": [[events_node["node_id"], i]]
            })
        elif m_init:
            oid = m_init.group(2)
            result.append({
                "id": "initial_" + oid,
                "time": float(m_init.group(1)),
                "kind": "object_initial",
                "entities": [oid],
                "fields": {"description": obj_info.get(oid, "Object " + oid)},
                "src": [[events_node["node_id"], i]]
            })

    return result


def outcomes(doc, scope):
    children_list = scope_nodes(doc, scope)
    events_node = None
    for node in children_list:
        if "Events" in node["title"]:
            events_node = node

    result = []
    if events_node is None:
        return result

    for i, line in enumerate(events_node["lines"]):
        # Collision event
        m_collide = re.match(r'Frame (\d+): Object (\d+) \(.+\) collides with Object (\d+) \(.+\)', line)
        if m_collide:
            result.append({
                "time": float(m_collide.group(1)),
                "kind": "collision",
                "entities": [m_collide.group(2), m_collide.group(3)],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })
            continue

        # Exit event (various phrasings)
        m_exit = re.match(r'Frame (\d+): Object (\d+) \(.+\) exits the scene\.', line)
        if not m_exit:
            m_exit = re.match(r'Frame (\d+): Object (\d+) \(.+\) leaves the scene\.', line)
        if m_exit:
            result.append({
                "time": float(m_exit.group(1)),
                "kind": "object_exit",
                "entities": [m_exit.group(2)],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })

    return result


def params(doc, scope):
    return {}


