import math
import re


def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    scope_title = scope if isinstance(scope, str) else scope.get("title", "")

    # Find motion log node robustly
    motion_node = None
    for n in doc.get("nodes", []):
        if n.get("kind") == "table" and "Motion log" in n.get("title", "") and scope_title in n.get("title", ""):
            motion_node = n
            break

    motion_data = {}
    if motion_node:
        for idx, rd in table_rows(motion_node):
            obj_str = rd.get("object", "")
            m = re.match(r'(\d+)', obj_str)
            if m:
                oid = m.group(1)
                if oid not in motion_data:
                    motion_data[oid] = []
                try:
                    motion_data[oid].append({
                        "f": float(rd["frame"]),
                        "x": float(rd["x"]), "y": float(rd["y"]),
                        "vx": float(rd["vx"]), "vy": float(rd["vy"])
                    })
                except (ValueError, TypeError):
                    pass
        for oid in motion_data:
            motion_data[oid].sort(key=lambda e: e["f"])

    if horizon is None:
        try:
            horizon = recorded_end(doc, scope) or 127.0
        except:
            horizon = 127.0
    if start is None:
        start = 0.0

    FRIC = 0.995
    COLL_DIST = 1.0
    EXIT_BOUND = 3.0
    METAL_MASS = 2.0
    RUBBER_MASS = 1.0

    obj_entries = {}
    for inp in inputs:
        if inp.get("kind") in ("object_initial", "object_enter"):
            obj_entries[inp["entities"][0]] = inp

    state = {}
    for oid, inp in obj_entries.items():
        entry_time = inp["time"]
        if entry_time > horizon + 1.0:
            continue

        desc = inp.get("fields", {}).get("description", "")
        mass = METAL_MASS if "metal" in desc else RUBBER_MASS

        target = max(start, entry_time)
        entries = motion_data.get(oid, [])
        x, y, vx, vy = 0.0, 0.0, 0.0, 0.0

        if entries:
            best = min(entries, key=lambda e: abs(e["f"] - target))
            x, y = best["x"], best["y"]

            nearby = sorted(entries, key=lambda e: abs(e["f"] - target))
            if len(nearby) >= 2:
                e1, e2 = nearby[0], nearby[1]
                df = e2["f"] - e1["f"]
                if df > 0:
                    vx = (e2["x"] - e1["x"]) / df
                    vy = (e2["y"] - e1["y"]) / df
                else:
                    vx, vy = best["vx"], best["vy"]
            else:
                vx, vy = best["vx"], best["vy"]

        state[oid] = {
            "x": x, "y": y, "vx": vx, "vy": vy,
            "mass": mass,
            "active": entry_time <= start + 0.5,
            "entry_time": entry_time
        }

    outcomes = []
    t = int(start) + 1
    collided_pairs = set()

    while t <= horizon:
        for oid, s in state.items():
            if not s["active"] and s["entry_time"] <= t:
                s["active"] = True

        active = [oid for oid, s in state.items() if s["active"]]

        for oid in active:
            s = state[oid]
            s["x"] += s["vx"]
            s["y"] += s["vy"]
            s["vx"] *= FRIC
            s["vy"] *= FRIC

        for i, o1 in enumerate(active):
            for o2 in active[i + 1:]:
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue

                s1, s2 = state[o1], state[o2]
                dx, dy = s2["x"] - s1["x"], s2["y"] - s1["y"]
                dist = math.hypot(dx, dy)

                if dist < COLL_DIST and dist > 0.01:
                    nx, ny = dx / dist, dy / dist
                    dvn = (s1["vx"] - s2["vx"]) * nx + (s1["vy"] - s2["vy"]) * ny

                    if dvn > 0.01:
                        m1, m2 = s1["mass"], s2["mass"]
                        J = 2.0 * dvn * m1 * m2 / (m1 + m2)
                        s1["vx"] -= J / m1 * nx
                        s1["vy"] -= J / m1 * ny
                        s2["vx"] += J / m2 * nx
                        s2["vy"] += J / m2 * ny

                        overlap = COLL_DIST - dist
                        if overlap > 0:
                            s1["x"] -= overlap * nx * 0.5
                            s1["y"] -= overlap * ny * 0.5
                            s2["x"] += overlap * nx * 0.5
                            s2["y"] += overlap * ny * 0.5

                        collided_pairs.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })

        for oid in list(active):
            s = state[oid]
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                s["active"] = False
                outcomes.append({
                    "time": float(t),
                    "kind": "object_exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

        t += 1

    return outcomes

