import math
from collections import defaultdict

def get_all_data():
    all_data = {}
    for node in doc["nodes"]:
        if node["kind"] == "text" and node["title"].startswith("Video "):
            vid = node["title"]
            children = [n for n in doc["nodes"] if n.get("parent_id") == node["node_id"]]
            events_node = None
            motion_node = None
            for c in children:
                if "Events" in c["title"]: events_node = c
                if "Motion log" in c["title"]: motion_node = c

            events = []
            if events_node:
                import re
                for line in events_node["lines"]:
                    m_enter = re.match(r'Frame (\d+): Object (\d+) \(.+\) enters the scene\.', line)
                    m_init = re.match(r'Frame (\d+): Object (\d+) \(.+\) is in view when the video begins\.', line)
                    m_collide = re.match(r'Frame (\d+): Object (\d+) \(.+\) collides with Object (\d+) \(.+\)', line)
                    m_exit = re.match(r'Frame (\d+): Object (\d+) \(.+\) (exits|leaves) the scene\.', line)
                    if m_enter or m_init:
                        events.append({"frame": int((m_enter or m_init).group(1)), "obj": (m_enter or m_init).group(2), "type": "enter"})
                    elif m_collide:
                        events.append({"frame": int(m_collide.group(1)), "objs": [m_collide.group(2), m_collide.group(3)], "type": "collide"})
                    elif m_exit:
                        events.append({"frame": int(m_exit.group(1)), "obj": m_exit.group(2), "type": "exit"})

            motion = []
            if motion_node:
                for row in motion_node["table"]["rows"]:
                    motion.append({
                        "frame": int(row[0]),
                        "obj": row[1].split()[0],
                        "x": float(row[2]), "y": float(row[3]),
                        "vx": float(row[4]), "vy": float(row[5]),
                        "speed": float(row[6])
                    })
            all_data[vid] = {"events": events, "motion": motion}
    return all_data

