# Compute friction estimates
friction_deltas = []
for v, vdata in data.items():
    objs = defaultdict(list)
    for m in vdata["motion"]:
        objs[m["obj"]].append(m)

    for oid, logs in objs.items():
        logs.sort(key=lambda x: x["frame"])
        coll_frames = set()
        for e in vdata["events"]:
            if e["type"] == "collide":
                coll_frames.add(e["frame"])

        for i in range(1, len(logs)):
            p1, p2 = logs[i-1], logs[i]
            dt = p2["frame"] - p1["frame"]
            if dt <= 0: continue
            # Skip if collision happened in between
            has_coll = any(f in coll_frames for f in range(p1["frame"]+1, p2["frame"]))
            if has_coll: continue

            delta_s = p1["speed"] - p2["speed"]
            if delta_s > 0:
                friction_deltas.append(delta_s / dt)

print(f"Friction estimates (mean, median, count):")
