        scope = get_node_by_title(doc, vid)
        children = [n for n in doc["nodes"] if n.get("parent_id") == scope["node_id"]]
        objs_node = events_node = motion_node = None
        for c in children:
            if ": Objects" in c["title"]: objs_node = c
            elif ": Events" in c["title"]: events_node = c
            elif ": Motion log" in c["title"]: motion_node = c

        obj_info = {}
        if objs_node:
            for line in objs_node["lines"]:
                m = re.match(r'Object (\d+): (.+)', line)
                if m: obj_info[m.group(1)] = m.group(2)

        events_raw = events_node["lines"] if events_node else []
        motion = []
        if motion_node:
            for row in motion_node["table"]["rows"]:
                motion.append({"frame": int(row[0]), "obj": row[1].split()[0], "x": float(row[2]), "y": float(row[3]), "vx": float(row[4]), "vy": float(row[5]), "speed": float(row[6])})

        all_data[vid] = {"objs": obj_info, "events": events_raw, "motion": motion}

