    for line in d["events"]:
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) (exits|leaves) the scene\.', line)
        if m:
            f, oid = int(m.group(1)), m.group(2)
            logs = [r for r in d["motion"] if r["obj"] == oid]
            if logs:
                last = max(logs, key=lambda x: x["frame"])
                exit_xs.append(last["x"])
