print(f"Exit Y: [{min(exit_ys)}, {max(exit_ys)}]")

coll_dists = []
for vid, d in all_data.items():
    for line in d["events"]:
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) collides with Object (\d+) \(.+\)', line)
        if m:
            f, o1, o2 = int(m.group(1)), m.group(2), m.group(3)
            l1 = sorted([r for r in d["motion"] if r["obj"] == o1], key=lambda x: x["frame"])
