            p1 = max((r for r in l1 if r["frame"] <= f), default=None, key=lambda x: x["frame"])
            p2 = max((r for r in l2 if r["frame"] <= f), default=None, key=lambda x: x["frame"])
            if p1 and p2:
                dist = math.sqrt((p1["x"]-p2["x"])**2 + (p1["y"]-p2["y"])**2)
                coll_dists.append((vid, f, o1, o2, dist))

print("\nCollision distances:")
