import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    scope_node = node_by_title(doc, scope) if isinstance(scope, str) else scope
    children = scope_nodes(doc, scope_node)
    motion_node = next((c for c in children if "Motion log" in c.get("title", "")), None)

    motion_data = []
    if motion_node:
        for _, rd in table_rows(motion_node):
            try:
                motion_data.append({
                    "frame": float(rd["frame"]),
                    "obj": rd["object"].split()[0],
                    "x": float(rd["x"]), "y": float(rd["y"]),
                    "vx": float(rd["vx"]), "vy": float(rd["vy"])
                })
            except (ValueError, TypeError, KeyError):
                pass

    if horizon is None:
        horizon = recorded_end(doc, scope_node)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = 128.0

    state = {}
    for inp in inputs:
        oid = inp["entities"][0]
        if inp["time"] <= start:
            logs = [m for m in motion_data if m["obj"] == oid]
            prev = sorted([l for l in logs if l["frame"] <= start], key=lambda l: l["frame"])
            if prev:
                p = prev[-1]
                state[oid] = {"x": p["x"], "y": p["y"], "vx": p["vx"], "vy": p["vy"], "active": True, "exited": False, "cooldown": 0}
            else:
                state[oid] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0, "active": True, "exited": False, "cooldown": 0}
        else:
            logs = [m for m in motion_data if m["obj"] == oid]
            first = sorted(logs, key=lambda l: l["frame"])[0] if logs else {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0}
            state[oid] = {"x": first["x"], "y": first["y"], "vx": first["vx"], "vy": first["vy"], "active": False, "exited": False, "cooldown": 0, "entry_time": inp["time"]}

    outcomes = []
    t = start
    dt = 1.0
    COLL_DIST = 0.5
    FRICTION = 0.01
    BOUND = 2.5

    while t < horizon:
        for oid, s in state.items():
            if not s["active"] and not s["exited"] and t >= s.get("entry_time", 0):
                s["active"] = True

            if s["active"] and not s["exited"]:
                speed = math.sqrt(s["vx"]**2 + s["vy"]**2)
                if speed > 0:
                    new_sp = max(0.0, speed - FRICTION)
                    fac = new_sp / speed
                    s["vx"] *= fac
                    s["vy"] *= fac
                    if abs(s["vx"]) < 1e-4: s["vx"] = 0.0
                    if abs(s["vy"]) < 1e-4: s["vy"] = 0.0

                s["x"] += s["vx"] * dt
                s["y"] += s["vy"] * dt
                if s["cooldown"] > 0:
                    s["cooldown"] -= 1

        for oid, s in state.items():
            if s["active"] and not s["exited"]:
                if abs(s["x"]) > BOUND or abs(s["y"]) > BOUND:
                    s["exited"] = True
                    outcomes.append({"time": round(t, 1), "kind": "object_exit", "entities": [oid], "value": None, "src": []})

        active_ids = [o for o, s in state.items() if s["active"] and not s["exited"]]
        for i in range(len(active_ids)):
            for j in range(i + 1, len(active_ids)):
                o1, o2 = active_ids[i], active_ids[j]
                s1, s2 = state[o1], state[o2]
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.sqrt(dx**2 + dy**2)

                if 0 < dist < COLL_DIST and s1["cooldown"] == 0 and s2["cooldown"] == 0:
                    outcomes.append({"time": round(t, 1), "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    s1["cooldown"] = 5
                    s2["cooldown"] = 5

                    nx = dx / dist
                    ny = dy / dist
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        s1["vx"] -= dvn * nx
                        s1["vy"] -= dvn * ny
                        s2["vx"] += dvn * nx
                        s2["vy"] += dvn * ny

                        overlap = COLL_DIST - dist
                        s1["x"] -= overlap * 0.5 * nx
                        s1["y"] -= overlap * 0.5 * ny
                        s2["x"] += overlap * 0.5 * nx
                        s2["y"] += overlap * 0.5 * ny

        t += dt

    return sorted(outcomes, key=lambda o: o["time"])

