import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    scope_node = node_by_title(doc, scope) if isinstance(scope, str) else scope
    children = scope_nodes(doc, scope_node)
    motion_node = next((c for c in children if "Motion log" in c.get("title", "")), None)

    motion_data = []
    if motion_node:
        for _, rd in table_rows(motion_node):
            try:
                motion_data.append({
                    "frame": float(rd["frame"]),
                    "obj": rd["object"].split()[0],
                    "x": float(rd["x"]), "y": float(rd["y"]),
                    "vx": float(rd["vx"]), "vy": float(rd["vy"])
                })
            except (ValueError, TypeError, KeyError):
                pass

    if horizon is None:
        horizon = recorded_end(doc, scope_node)
    if horizon is None:
        horizon = 128.0
    if start is None:
        start = 0.0

    obj_motion = {}
    for m in motion_data:
        obj_motion.setdefault(m["obj"], []).append(m)
    for oid in obj_motion:
        obj_motion[oid].sort(key=lambda x: x["frame"])

    state = {}
    for inp in inputs:
        oid = inp["entities"][0]
        entry_t = inp["time"]
        logs = obj_motion.get(oid, [])

        if entry_t <= start:
            prev = sorted([l for l in logs if l["frame"] <= start], key=lambda l: l["frame"])
            if prev:
                p = prev[-1]
                state[oid] = {"x": p["x"], "y": p["y"], "vx": p["vx"], "vy": p["vy"],
                              "active": True, "exited": False, "cooldown": 0}
            elif logs:
                p = logs[0]
                state[oid] = {"x": p["x"], "y": p["y"], "vx": p["vx"], "vy": p["vy"],
                              "active": True, "exited": False, "cooldown": 0}
            else:
                state[oid] = {"x": 0, "y": 0, "vx": 0, "vy": 0,
                              "active": True, "exited": False, "cooldown": 0}
        else:
            logs_after = [l for l in logs if l["frame"] >= entry_t]
            if logs_after:
                p = min(logs_after, key=lambda l: abs(l["frame"] - entry_t))
                state[oid] = {"x": p["x"], "y": p["y"], "vx": p["vx"], "vy": p["vy"],
                              "active": False, "exited": False, "cooldown": 0, "entry_time": entry_t}
            else:
                state[oid] = {"x": 0, "y": 0, "vx": 0, "vy": 0,
                              "active": False, "exited": False, "cooldown": 0, "entry_time": entry_t}

    outcomes = []
    t = start
    dt = 0.1

    while t <= horizon:
        for oid, s in state.items():
            if not s["active"] and not s.get("exited"):
                if "entry_time" in s and t >= s["entry_time"]:
                    s["active"] = True

        for oid, s in state.items():
            if s["active"] and not s.get("exited"):
                speed = math.sqrt(s["vx"]**2 + s["vy"]**2)
                if speed > 0.01:
                    new_speed = max(0.0, speed - 0.01 * dt)
                    s["vx"] *= new_speed / speed
                    s["vy"] *= new_speed / speed

                s["x"] += s["vx"] * dt
                s["y"] += s["vy"] * dt

                if abs(s["x"]) > 2.5 or abs(s["y"]) > 2.5:
                    s["exited"] = True
                    outcomes.append({"time": t, "kind": "object_exit", "entities": [oid], "value": None, "src": []})

        active = [o for o, s in state.items() if s["active"] and not s.get("exited")]
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, o2 = active[i], active[j]
                s1, s2 = state[o1], state[o2]
                if s1.get("cooldown", 0) > 0 or s2.get("cooldown", 0) > 0:
                    continue
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                d = math.sqrt(dx**2 + dy**2)
                if 0 < d < 0.45:
                    outcomes.append({"time": t, "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    s1["cooldown"] = 5
                    s2["cooldown"] = 5

                    nx, ny = dx / d, dy / d
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        impulse = dvn * 0.8
                        s1["vx"] -= impulse * nx
                        s1["vy"] -= impulse * ny
                        s2["vx"] += impulse * nx
                        s2["vy"] += impulse * ny

                        overlap = 0.45 - d
                        s1["x"] -= overlap * 0.5 * nx
                        s1["y"] -= overlap * 0.5 * ny
                        s2["x"] += overlap * 0.5 * nx
                        s2["y"] += overlap * 0.5 * ny

        t += dt

    return sorted(outcomes, key=lambda o: o["time"])

