                state[oid] = {"x": p["x"], "y": p["y"], "vx": p["vx"], "vy": p["vy"],
                              "active": False, "exited": False, "cooldown": 0.0, "entry_time": entry_t}
            else:
                state[oid] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0,
                              "active": False, "exited": False, "cooldown": 0.0, "entry_time": entry_t}

    outcomes = []
    t = start
    dt = 0.1

    while t < horizon:
        for oid, s in state.items():
            if not s["active"] and not s["exited"]:
                if t >= s.get("entry_time", 0):
                    s["active"] = True

        for oid, s in state.items():
            if s["active"] and not s["exited"]:
                speed = math.sqrt(s["vx"]**2 + s["vy"]**2)
                if speed > 1e-3:
                    new_speed = max(0.0, speed - 0.012 * dt)
                    s["vx"] *= new_speed / speed
                    s["vy"] *= new_speed / speed
                else:
                    s["vx"] = 0.0
                    s["vy"] = 0.0

                s["x"] += s["vx"] * dt
                s["y"] += s["vy"] * dt

                if abs(s["x"]) > 2.5 or abs(s["y"]) > 2.5:
                    s["exited"] = True
                    outcomes.append({"time": round(t, 1), "kind": "object_exit", "entities": [oid], "value": None, "src": []})

        active = [o for o, s in state.items() if s["active"] and not s["exited"]]
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, o2 = active[i], active[j]
                s1, s2 = state[o1], state[o2]
                if s1["cooldown"] > 0 or s2["cooldown"] > 0:
                    continue

                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                d = math.sqrt(dx*dx + dy*dy)

                if 0 < d < 0.43:
                    outcomes.append({"time": round(t, 1), "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    s1["cooldown"] = 3.0
                    s2["cooldown"] = 3.0

                    nx, ny = dx/d, dy/d
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx*nx + dvy*ny

                    if dvn > 0:
                        s1["vx"] -= dvn * nx * 0.85
                        s1["vy"] -= dvn * ny * 0.85
                        s2["vx"] += dvn * nx * 0.85
                        s2["vy"] += dvn * ny * 0.85

                        overlap = 0.43 - d
                        s1["x"] -= overlap * 0.5 * nx
                        s1["y"] -= overlap * 0.5 * ny
                        s2["x"] += overlap * 0.5 * nx
                        s2["y"] += overlap * 0.5 * ny

        for oid, s in state.items():
            if s["cooldown"] > 0:
                s["cooldown"] -= dt

        t += dt

    return sorted(outcomes, key=lambda o: o["time"])

