import math
import re


def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    Forward model for CLEVRER physics videos.
    Objects slide on a flat floor with friction and collide elastically.
    """
    scope_node = node_by_title(doc, scope)
    children = scope_nodes(doc, scope_node)

    # ---- Parse motion log from document (for state initialisation) ----
    motion_node = next((c for c in children if "Motion log" in c["title"]), None)
    motion_data = {}  # {oid: [{frame, x, y, vx, vy, speed}, ...]}
    if motion_node:
        for idx, rd in table_rows(motion_node):
            obj_str = rd.get("object", "")
            m = re.match(r'(\d+)', obj_str)
            if m:
                oid = m.group(1)
                if oid not in motion_data:
                    motion_data[oid] = []
                if rd.get("x", "") == "" or rd.get("y", "") == "":
                    continue
                try:
                    motion_data[oid].append({
                        "frame": float(rd["frame"]),
                        "x": float(rd["x"]), "y": float(rd["y"]),
                        "vx": float(rd["vx"]), "vy": float(rd["vy"]),
                        "speed": float(rd["speed"])
                    })
                except (ValueError, TypeError):
                    pass
        for oid in motion_data:
            motion_data[oid].sort(key=lambda r: r["frame"])

    # ---- Parse inputs ----
    obj_entries = {}  # {oid: input_record}
    for inp in inputs:
        oid = inp["entities"][0]
        obj_entries[oid] = inp

    # ---- Defaults ----
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    if start is None:
        start = 0.0

    # ---- Physical constants (estimated from data) ----
    THRESHOLD = 1.0       # collision distance threshold (sum of radii)
    FRICTION = 0.993      # velocity multiplier per frame (kinetic friction)
    BOUNDARY = 3.0        # scene boundary half-width

    # ---- Initialise state at `start` ----
    state = {}  # {oid: {x, y, vx, vy, mass, active, entry_time}}
    for oid, inp in obj_entries.items():
        entry_time = inp["time"]
        if entry_time > horizon:
            continue

        desc = inp.get("fields", {}).get("description", "")
        mass = 2.0 if "metal" in desc else 1.0

        x, y, vx, vy = 0.0, 0.0, 0.0, 0.0

        if oid in motion_data:
            entries = motion_data[oid]
            target = max(start, entry_time)

            # Latest entry at or before target
            entries_before = [r for r in entries if r["frame"] <= target]
            if entries_before:
                best = max(entries_before, key=lambda r: r["frame"])
                x, y = best["x"], best["y"]
                # Estimate velocity from two entries closest to target
                nearby = sorted(entries, key=lambda r: abs(r["frame"] - target))
                if len(nearby) >= 2:
                    r1, r2 = nearby[0], nearby[1]
                    dt_diff = r2["frame"] - r1["frame"]
                    if dt_diff > 0:
                        vx = (r2["x"] - r1["x"]) / dt_diff
                        vy = (r2["y"] - r1["y"]) / dt_diff
            else:
                best = min(entries, key=lambda r: abs(r["frame"] - entry_time))
                x, y = best["x"], best["y"]

        state[oid] = {
            "x": x, "y": y, "vx": vx, "vy": vy,
            "mass": mass, "active": entry_time <= start,
            "entry_time": entry_time
        }

    # ---- Simulate forward (frame-by-frame) ----
    outcomes = []
    t = start
    dt = 1.0  # one frame per step

    while t <= horizon:
        # Activate objects that enter at or before current time
        for oid, s in state.items():
            if not s["active"] and s["entry_time"] <= t:
                s["active"] = True

        active = [oid for oid, s in state.items() if s["active"]]

        # Apply friction and update positions
        for oid in active:
            s = state[oid]
            s["vx"] *= FRICTION
            s["vy"] *= FRICTION
            s["x"] += s["vx"] * dt
            s["y"] += s["vy"] * dt

        # Check for collisions
        for i, oid1 in enumerate(active):
            for oid2 in active[i + 1:]:
                s1, s2 = state[oid1], state[oid2]
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < THRESHOLD:
                    # Normal direction from oid1 to oid2
                    if dist > 0:
                        nx, ny = dx / dist, dy / dist
                    else:
                        nx, ny = 1.0, 0.0

                    # Relative velocity along normal
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    # Only collide if approaching
                    if dvn > 0:
                        m1, m2 = s1["mass"], s2["mass"]
                        J = 2 * dvn * m1 * m2 / (m1 + m2)
                        s1["vx"] -= J / m1 * nx
                        s1["vy"] -= J / m1 * ny
                        s2["vx"] += J / m2 * nx
                        s2["vy"] += J / m2 * ny

                        # Separate overlapping objects
                        overlap = THRESHOLD - dist
                        if overlap > 0:
                            s1["x"] -= overlap * nx / 2
                            s1["y"] -= overlap * ny / 2
                            s2["x"] += overlap * nx / 2
                            s2["y"] += overlap * ny / 2

                        outcomes.append({
                            "time": round(t, 1),
                            "kind": "collision",
                            "entities": sorted([oid1, oid2]),
                            "value": None,
                            "src": []
                        })

        # Check for exits
        for oid in list(active):
            s = state[oid]
            if abs(s["x"]) > BOUNDARY or abs(s["y"]) > BOUNDARY:
                s["active"] = False
                outcomes.append({
                    "time": round(t, 1),
                    "kind": "object_exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

        t += dt

    return outcomes

