import math
import re


def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    Forward model for CLEVRER physics videos.
    Uses inputs to determine which objects exist, when they enter.
    Uses motion log from document for state initialisation at start.
    Simulates forward with friction and elastic collisions.
    """
    scope_node = node_by_title(doc, scope)
    children = scope_nodes(doc, scope_node)

    # Parse motion log
    motion_node = next((c for c in children if "Motion log" in c["title"]), None)
    motion_data = {}
    if motion_node:
        for idx, rd in table_rows(motion_node):
            obj_str = rd.get("object", "")
            m = re.match(r'(\d+)', obj_str)
            if m and rd.get("x", "") != "" and rd.get("y", "") != "":
                try:
                    oid = m.group(1)
                    if oid not in motion_data:
                        motion_data[oid] = []
                    motion_data[oid].append({
                        "frame": float(rd["frame"]),
                        "x": float(rd["x"]), "y": float(rd["y"]),
                        "vx": float(rd["vx"]), "vy": float(rd["vy"]),
                        "speed": float(rd["speed"])
                    })
                except (ValueError, TypeError):
                    pass
        for oid in motion_data:
            motion_data[oid].sort(key=lambda r: r["frame"])

    # Get objects list for material info
    objects_node = next((c for c in children if ": Objects" in c["title"]), None)
    obj_materials = {}
    if objects_node:
        for line in objects_node.get("lines", []):
            m = re.match(r'Object (\d+): (.+)', line)
            if m:
                obj_materials[m.group(1)] = m.group(2)

    # Defaults
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    if start is None:
        start = 0.0

    # Physics parameters
    FRIC = 0.993  # velocity multiplier per frame
    COLL_RADIUS = 1.0  # collision threshold (sum of radii for unit-sized objects)
    BOUNDARY = 3.0  # exit threshold
    METAL_MASS = 2.0
    RUBBER_MASS = 1.0

    # Determine active objects from inputs
    obj_entries = {}
    for inp in inputs:
        if inp["kind"] in ("object_initial", "object_enter"):
            oid = inp["entities"][0]
            obj_entries[oid] = inp

    # Initialise state
    state = {}
    for oid, inp in obj_entries.items():
        entry_time = inp["time"]
        if entry_time > horizon:
            continue

        # Determine mass from description
        desc = inp.get("fields", {}).get("description", "")
        if not desc:
            desc = obj_materials.get(oid, "")
        mass = METAL_MASS if "metal" in desc else RUBBER_MASS

        # Get initial state from motion data
        target = max(start, entry_time)
        entries = motion_data.get(oid, [])

        x, y, vx, vy = 0.0, 0.0, 0.0, 0.0
        if entries:
            # Find entry closest to or before target
            before = [e for e in entries if e["frame"] <= target]
            if before:
                best = max(before, key=lambda e: e["frame"])
                x, y = best["x"], best["y"]
                vx, vy = best["vx"], best["vy"]
            else:
                best = min(entries, key=lambda e: abs(e["frame"] - target))
                x, y = best["x"], best["y"]
                vx, vy = best["vx"], best["vy"]

        state[oid] = {
            "x": x, "y": y, "vx": vx, "vy": vy,
            "mass": mass,
            "active": entry_time <= start,
            "entry_time": entry_time,
            "has_collided_with": set()  # track collisions to avoid duplicates
        }

    # Simulate
    outcomes = []
    t = start
    dt = 1.0
    collision_pairs = set()  # track which pairs have collided

    while t <= horizon:
        # Activate entering objects
        for oid, s in state.items():
            if not s["active"] and s["entry_time"] <= t:
                s["active"] = True

        active = [oid for oid, s in state.items() if s["active"]]

        # Update positions
        for oid in active:
            s = state[oid]
            s["x"] += s["vx"] * dt
            s["y"] += s["vy"] * dt
            # Apply friction
            s["vx"] *= FRIC
            s["vy"] *= FRIC

        # Check collisions
        for i, oid1 in enumerate(active):
            for oid2 in active[i + 1:]:
                pair = tuple(sorted([oid1, oid2]))
                if pair in collision_pairs:
                    continue

                s1, s2 = state[oid1], state[oid2]
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < COLL_RADIUS and dist > 0:
                    # Normal from 1 to 2
                    nx, ny = dx / dist, dy / dist

                    # Relative velocity
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    # Only respond if approaching
                    if dvn > 0:
                        m1, m2 = s1["mass"], s2["mass"]
                        J = 2.0 * dvn * m1 * m2 / (m1 + m2)
                        s1["vx"] -= J / m1 * nx
                        s1["vy"] -= J / m1 * ny
                        s2["vx"] += J / m2 * nx
                        s2["vy"] += J / m2 * ny

                        # Separate
                        overlap = COLL_RADIUS - dist
                        if overlap > 0:
                            s1["x"] -= overlap * nx * 0.5
                            s1["y"] -= overlap * ny * 0.5
                            s2["x"] += overlap * nx * 0.5
                            s2["y"] += overlap * ny * 0.5

                        collision_pairs.add(pair)
                        outcomes.append({
                            "time": round(t),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })

        # Check exits
        for oid in list(active):
            s = state[oid]
            if abs(s["x"]) > BOUNDARY or abs(s["y"]) > BOUNDARY:
                s["active"] = False
                outcomes.append({
                    "time": round(t),
                    "kind": "object_exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

        t += dt

    return outcomes

