            if not s["active"] and s["entry_time"] <= t:
                s["active"] = True

        active = [oid for oid, s in state.items() if s["active"]]

        # Update positions and apply friction
        for oid in active:
            s = state[oid]
            s["x"] += s["vx"]
            s["y"] += s["vy"]
            s["vx"] *= FRIC
            s["vy"] *= FRIC

        # Check collisions
        for i, o1 in enumerate(active):
            for o2 in active[i + 1:]:
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue

                s1, s2 = state[o1], state[o2]
                dx, dy = s2["x"] - s1["x"], s2["y"] - s1["y"]
                dist = math.hypot(dx, dy)

                if dist < COLL_DIST and dist > 0.01:
                    nx, ny = dx / dist, dy / dist
                    dvn = (s1["vx"] - s2["vx"]) * nx + (s1["vy"] - s2["vy"]) * ny

                    if dvn > 0.01:  # Approaching
                        m1, m2 = s1["mass"], s2["mass"]
                        J = 2.0 * dvn * m1 * m2 / (m1 + m2)
                        s1["vx"] -= J / m1 * nx
                        s1["vy"] -= J / m1 * ny
                        s2["vx"] += J / m2 * nx
                        s2["vy"] += J / m2 * ny

                        # Separate overlapping objects
                        overlap = COLL_DIST - dist
                        if overlap > 0:
                            s1["x"] -= overlap * nx * 0.5
                            s1["y"] -= overlap * ny * 0.5
                            s2["x"] += overlap * nx * 0.5
                            s2["y"] += overlap * ny * 0.5

                        collided_pairs.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })

        # Check exits
        for oid in list(active):
            s = state[oid]
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                s["active"] = False
                outcomes.append({
                    "time": float(t),
                    "kind": "object_exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

        t += 1

    return outcomes

