    # Object metadata from inputs
    obj_info = {}
    for inp in inputs:
        for eid in inp["entities"]:
            desc = inp["fields"].get("description", "")
            obj_info[eid] = "metal" if "metal" in desc else "rubber"

    # Time range
    t0 = start if start is not None else 0.0
    t1 = horizon if horizon is not None else recorded_end(doc, scope)
    if t1 is None:
        t1 = 127.0

    # Initialize state at t0
    state = {}
    FR = 0.9924  # per-frame speed retention (friction ~0.76%/frame)

    for inp in inputs:
        eid = inp["entities"][0]
        et = inp["time"]
        mat = obj_info[eid]

        if inp["kind"] == "object_initial":
            recs = obj_motion.get(eid, [])
            prev = max((r for r in recs if r["f"] <= t0), key=lambda r: r["f"], default=None)
            if prev:
                dt = t0 - prev["f"]
                state[eid] = dict(x=prev["x"] + prev["vx"] * dt,
                                  y=prev["y"] + prev["vy"] * dt,
                                  vx=prev["vx"] * (FR ** dt),
                                  vy=prev["vy"] * (FR ** dt),
                                  mat=mat, active=True, entered=True)
            elif recs:
                state[eid] = dict(x=recs[0]["x"], y=recs[0]["y"],
                                  vx=recs[0]["vx"], vy=recs[0]["vy"],
                                  mat=mat, active=True, entered=True)
            else:
                state[eid] = dict(x=0, y=0, vx=0, vy=0,
                                  mat=mat, active=True, entered=True)

        elif inp["kind"] == "object_enter":
            if t0 < et:
                state[eid] = dict(x=0, y=0, vx=0, vy=0, mat=mat,
                                  active=False, entered=False, enter_t=et)
            else:
                recs = obj_motion.get(eid, [])
                if recs:
                    nxt = min((r for r in recs if r["f"] >= et),
                              key=lambda r: r["f"], default=None)
                    if nxt:
                        dt = t0 - nxt["f"]
                        state[eid] = dict(x=nxt["x"] + nxt["vx"] * dt,
                                          y=nxt["y"] + nxt["vy"] * dt,
                                          vx=nxt["vx"] * (FR ** dt),
                                          vy=nxt["vy"] * (FR ** dt),
                                          mat=mat, active=True, entered=True)
                    else:
                        state[eid] = dict(x=recs[0]["x"], y=recs[0]["y"],
                                          vx=recs[0]["vx"], vy=recs[0]["vy"],
                                          mat=mat, active=True, entered=True)
                else:
                    state[eid] = dict(x=0, y=0, vx=0, vy=0,
                                      mat=mat, active=True, entered=True)

    # Physics parameters
    CR = 0.48       # collision radius (distance threshold)
    FRIC = 0.0076   # per-frame friction coefficient

    def restitution(m1, m2):
        if m1 == m2 == "rubber":
            return 0.06
        if m1 == m2 == "metal":
            return 0.9
        return 0.5

    outcomes = []
    t = t0
    dt = 1.0
    seen = set()

    while t < t1:
        # Activate entering objects
        for eid, s in state.items():
            if not s["entered"] and s.get("enter_t", 1e9) <= t:
                r0 = obj_motion.get(eid, [])
                if r0:
                    s["x"], s["y"] = r0[0]["x"], r0[0]["y"]
                    s["vx"], s["vy"] = r0[0]["vx"], r0[0]["vy"]
                s["entered"] = True
                s["active"] = True

        # Integrate motion
        for s in state.values():
            if s["active"]:
                s["x"] += s["vx"] * dt
                s["y"] += s["vy"] * dt
                s["vx"] *= (1 - FRIC)
                s["vy"] *= (1 - FRIC)

        # Collision detection & response
        active = [eid for eid, s in state.items() if s["active"]]
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                a, b = active[i], active[j]
                sa, sb = state[a], state[b]
                dx = sb["x"] - sa["x"]
                dy = sb["y"] - sa["y"]
                d = math.sqrt(dx * dx + dy * dy)
                if 0 < d < CR:
                    nx, ny = dx / d, dy / d
                    dvn = (sa["vx"] - sb["vx"]) * nx + (sa["vy"] - sb["vy"]) * ny
                    if dvn > 0:  # objects approaching
                        k = (min(a, b), max(a, b), int(t))
                        if k not in seen:
                            seen.add(k)
                            e = restitution(sa["mat"], sb["mat"])
                            J = (1 + e) * dvn / 2  # impulse magnitude (equal mass)
                            sa["vx"] -= J * nx
                            sa["vy"] -= J * ny
                            sb["vx"] += J * nx
                            sb["vy"] += J * ny
                            outcomes.append({
                                "time": float(t),
                                "kind": "collision",
                                "entities": [min(a, b), max(a, b)],
                                "value": None,
                                "src": []
                            })

        # Exit detection
        for eid, s in state.items():
            if s["active"] and (abs(s["x"]) > 5.0 or abs(s["y"]) > 5.0):
                s["active"] = False
                outcomes.append({
                    "time": float(t),
                    "kind": "object_exit",
                    "entities": [eid],
                    "value": None,
                    "src": []
                })

        t += dt

    return outcomes

