import math
from collections import defaultdict


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Read motion data
    motion_rows = []
    for node in scope_nodes(doc, scope):
        if "Motion log" in node["title"] and node["kind"] == "table":
            motion_rows = node["table"]["rows"]
            break

    obj_data = defaultdict(list)
    for row in motion_rows:
        if not row or not row[0] or not row[1]:
            continue
        try:
            f = int(float(row[0]))
            oid = row[1].split()[0]
            obj_data[oid].append({
                "f": f, "x": float(row[2]), "y": float(row[3]),
                "vx": float(row[4]), "vy": float(row[5])
            })
        except (ValueError, IndexError):
            continue

    for oid in obj_data:
        obj_data[oid].sort(key=lambda r: r["f"])

    # Entry times from inputs
    entry_times = {}
    for inp in inputs:
        for eid in inp["entities"]:
            entry_times[eid] = inp["time"]

    t0 = start if start is not None else 0.0
    t1 = horizon if horizon is not None else recorded_end(doc, scope)
    if t1 is None:
        t1 = 127.0

    # Collision radius calibrated from Video 14934 data where collision distance ~0.475
    CR = 0.48
    # Screen boundary for exit detection
    B = 3.0

    def get_pos(oid, f):
        if oid not in entry_times or f < entry_times[oid]:
            return None
        data = obj_data.get(oid, [])
        if not data:
            return None
        if f <= data[0]["f"]:
            r = data[0]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt
        if f >= data[-1]["f"]:
            r = data[-1]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt
        # Linear interpolation between data points
        for i in range(len(data) - 1):
            if data[i]["f"] <= f < data[i + 1]["f"]:
                t = (f - data[i]["f"]) / (data[i + 1]["f"] - data[i]["f"])
                x = data[i]["x"] + t * (data[i + 1]["x"] - data[i]["x"])
                y = data[i]["y"] + t * (data[i + 1]["y"] - data[i]["y"])
                return x, y
        return None

    outcomes = []
    in_contact = {}

    f_start = max(int(math.ceil(t0)), 0)
    f_end = int(math.floor(t1))

    all_oids = sorted(set(list(obj_data.keys()) + list(entry_times.keys())))

    for f in range(f_start, f_end + 1):
        positions = {}
        for oid in all_oids:
            pos = get_pos(oid, f)
            if pos is not None:
                positions[oid] = pos

        oids = sorted(positions.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                a, b = oids[i], oids[j]
                key = (min(a, b), max(a, b))
                xa, ya = positions[a]
                xb, yb = positions[b]
                d = math.sqrt((xa - xb) ** 2 + (ya - yb) ** 2)
                if d < CR:
                    if not in_contact.get(key, False):
                        in_contact[key] = True
                        outcomes.append({
                            "time": float(f),
                            "kind": "collision",
                            "entities": [min(a, b), max(a, b)],
                            "value": None,
                            "src": []
                        })
                else:
                    in_contact[key] = False

    # Detect exits: objects whose last recorded frame is before horizon
    for oid in obj_data:
        if oid not in entry_times:
            continue
        data = obj_data[oid]
        if not data:
            continue
        last = data[-1]
        if last["f"] < t1:
            # Extrapolate trajectory from last data point
            x0, y0 = last["x"], last["y"]
            vx, vy = last["vx"], last["vy"]
            f0 = last["f"]
            exit_f = None
            for f in range(f0 + 1, int(t1) + 2):
                x = x0 + vx * (f - f0)
                y = y0 + vy * (f - f0)
                if abs(x) > B or abs(y) > B:
                    exit_f = f
                    break
            if exit_f is not None and exit_f > t0:
                outcomes.append({
                    "time": float(exit_f),
                    "kind": "object_exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

    return sorted(outcomes, key=lambda o: o["time"])

