import math
from collections import defaultdict


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    obj_data = defaultdict(list)
    for node in scope_nodes(doc, scope):
        if "Motion log" in node["title"] and node["kind"] == "table":
            for _, rd in table_rows(node):
                try:
                    if rd.get("frame") and rd.get("object"):
                        f = int(float(rd["frame"]))
                        oid = rd["object"].split()[0]
                        obj_data[oid].append({
                            "f": f, "x": float(rd["x"]), "y": float(rd["y"]),
                            "vx": float(rd["vx"]), "vy": float(rd["vy"])
                        })
                except:
                    continue
            break

    for oid in obj_data:
        obj_data[oid].sort(key=lambda r: r["f"])

    entry_times = {}
    for inp in inputs:
        for eid in inp["entities"]:
            entry_times[eid] = inp["time"]

    t0 = start if start is not None else 0.0
    t1 = horizon if horizon is not None else recorded_end(doc, scope)
    if t1 is None:
        t1 = 127.0

    def get_pos(oid, f):
        data = obj_data.get(oid, [])
        if not data:
            return None
        if f <= data[0]["f"]:
            r = data[0]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt
        if f >= data[-1]["f"]:
            r = data[-1]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt
        for i in range(len(data) - 1):
            if data[i]["f"] <= f <= data[i + 1]["f"]:
                t = (f - data[i]["f"]) / (data[i + 1]["f"] - data[i]["f"])
                return (data[i]["x"] + t * (data[i + 1]["x"] - data[i]["x"]),
                        data[i]["y"] + t * (data[i + 1]["y"] - data[i]["y"]))
        return None

    # Detect velocity discontinuities to find collision times
    vel_change_frames = defaultdict(list)
    for oid, data in obj_data.items():
        for i in range(1, len(data)):
            prev, curr = data[i - 1], data[i]
            dv = math.sqrt((curr["vx"] - prev["vx"]) ** 2 + (curr["vy"] - prev["vy"]) ** 2)
            dt = curr["f"] - prev["f"]
            if dt > 0:
                dv_rate = dv / dt
                # Significant velocity change indicates collision
                if dv_rate > 0.1:
                    vel_change_frames[curr["f"]].append(oid)

    CR = 1.0
    outcomes = []
    seen = set()

    # Collision times from velocity changes
    for f, oids in vel_change_frames.items():
        if f <= t0 or f > t1:
            continue
        oids = sorted(set(oids))
        if len(oids) >= 2:
            for i in range(len(oids)):
                for j in range(i + 1, len(oids)):
                    a, b = oids[i], oids[j]
                    key = (min(a, b), max(a, b))
                    pa = get_pos(a, f)
                    pb = get_pos(b, f)
                    if pa and pb:
                        d = math.sqrt((pa[0] - pb[0]) ** 2 + (pa[1] - pb[1]) ** 2)
                        if d < CR:
                            if key not in seen:
                                seen.add(key)
                                outcomes.append({
                                    "time": float(f),
                                    "kind": "collision",
                                    "entities": [min(a, b), max(a, b)],
                                    "value": None,
                                    "src": []
                                })

    # Also check proximity at all sampled frames
    all_frames = sorted(set(r["f"] for data in obj_data.values() for r in data))
    in_contact = {}
    CR2 = 0.6

    for f in all_frames:
        if f < t0 or f > t1:
            continue
        positions = {}
        for oid in obj_data:
            pos = get_pos(oid, f)
            if pos:
                positions[oid] = pos
        oids = sorted(positions.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                a, b = oids[i], oids[j]
                key = (min(a, b), max(a, b))
                xa, ya = positions[a]
                xb, yb = positions[b]
                d = math.sqrt((xa - xb) ** 2 + (ya - yb) ** 2)
                if d < CR2:
                    if not in_contact.get(key, False):
                        in_contact[key] = True
                        already = any(o["time"] == f and tuple(o["entities"]) == key for o in outcomes)
                        if not already:
                            outcomes.append({
                                "time": float(f),
                                "kind": "collision",
                                "entities": [min(a, b), max(a, b)],
                                "value": None,
                                "src": []
                            })
                else:
                    in_contact[key] = False

    # Exit detection: objects whose last data point is before t1 and
    # extrapolation goes off-screen
    B = 4.0
    for oid in obj_data:
        data = obj_data[oid]
        if not data or len(data) < 2:
            continue
        last = data[-1]
        # Only consider exit if object has been tracked for a while
        first = data[0]
        if last["f"] - first["f"] < 10:
            continue
        if last["f"] >= t1 - 2:
            continue
        x0, y0 = last["x"], last["y"]
        vx, vy = last["vx"], last["vy"]
        f0 = last["f"]
        # Check if moving toward boundary
        speed = math.sqrt(vx ** 2 + vy ** 2)
        if speed < 0.05:
            continue  # Not moving, won't exit
        exit_f = None
        for f in range(f0 + 1, int(t1) + 10):
            x = x0 + vx * (f - f0)
            y = y0 + vy * (f - f0)
            if abs(x) > B or abs(y) > B:
                exit_f = f
                break
        if exit_f and exit_f > t0:
            outcomes.append({
                "time": float(exit_f),
                "kind": "object_exit",
                "entities": [oid],
                "value": None,
