import math
from collections import defaultdict


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Parse motion data
    obj_data = defaultdict(list)
    for node in scope_nodes(doc, scope):
        if "Motion log" in node["title"] and node["kind"] == "table":
            for _, rd in table_rows(node):
                try:
                    if rd.get("frame") and rd.get("object"):
                        f = int(float(rd["frame"]))
                        oid = rd["object"].split()[0]
                        obj_data[oid].append({
                            "f": f, "x": float(rd["x"]), "y": float(rd["y"]),
                            "vx": float(rd["vx"]), "vy": float(rd["vy"])
                        })
                except:
                    continue
            break

    for oid in obj_data:
        obj_data[oid].sort(key=lambda r: r["f"])

    # Active objects from inputs
    active_oids = set()
    entry_times = {}
    for inp in inputs:
        for eid in inp["entities"]:
            active_oids.add(eid)
            entry_times[eid] = inp["time"]

    t0 = start if start is not None else 0.0
    t1 = horizon if horizon is not None else recorded_end(doc, scope)
    if t1 is None:
        t1 = 127.0

    def speed(r):
        return math.sqrt(r["vx"] ** 2 + r["vy"] ** 2)

    # Find velocity discontinuities for each object
    vel_jumps = defaultdict(list)  # frame -> [object_ids]
    for oid in active_oids:
        data = obj_data.get(oid, [])
        for i in range(1, len(data)):
            prev, curr = data[i - 1], data[i]
            dt = curr["f"] - prev["f"]
            if dt <= 0:
                continue
            dv = math.sqrt((curr["vx"] - prev["vx"]) ** 2 + (curr["vy"] - prev["vy"]) ** 2)
            dv_rate = dv / dt
            if dv_rate > 0.08:  # Significant velocity change
                vel_jumps[curr["f"]].append(oid)

    def get_state(oid, f):
        data = obj_data.get(oid, [])
        if not data:
            return None
        if f <= data[0]["f"]:
            r = data[0]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt
        if f >= data[-1]["f"]:
            r = data[-1]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt
        for i in range(len(data) - 1):
            if data[i]["f"] <= f <= data[i + 1]["f"]:
                t = (f - data[i]["f"]) / (data[i + 1]["f"] - data[i]["f"])
                return (data[i]["x"] + t * (data[i + 1]["x"] - data[i]["x"]),
                        data[i]["y"] + t * (data[i + 1]["y"] - data[i]["y"]))
        return None

    outcomes = []
    seen = set()
    CR = 0.7

    # Collision detection from velocity jumps
    for f, oids in vel_jumps.items():
        if f <= t0 or f > t1:
            continue
        # Only consider active objects that should be present at this frame
        present = [o for o in set(oids) if o in active_oids and f >= entry_times.get(o, 0)]
        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                a, b = present[i], present[j]
                key = (min(a, b), max(a, b))
                pa = get_state(a, f)
                pb = get_state(b, f)
                if pa and pb:
                    d = math.sqrt((pa[0] - pb[0]) ** 2 + (pa[1] - pb[1]) ** 2)
                    if d < CR and key not in seen:
                        seen.add(key)
                        outcomes.append({
                            "time": float(f),
                            "kind": "collision",
                            "entities": [min(a, b), max(a, b)],
                            "value": None,
                            "src": []
                        })

    # Also check proximity at all frames for objects that are both active
    all_frames = sorted(set(
        r["f"] for oid in active_oids
        for r in obj_data.get(oid, [])
    ))
    in_contact = {}
    CR2 = 0.5

    for f in all_frames:
        if f < t0 or f > t1:
            continue
        positions = {}
        for oid in active_oids:
            if f < entry_times.get(oid, 0):
                continue
            pos = get_state(oid, f)
            if pos is not None:
                positions[oid] = pos
        oids = sorted(positions.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                a, b = oids[i], oids[j]
                key = (min(a, b), max(a, b))
                xa, ya = positions[a]
                xb, yb = positions[b]
                d = math.sqrt((xa - xb) ** 2 + (ya - yb) ** 2)
                if d < CR2:
                    if not in_contact.get(key, False):
                        in_contact[key] = True
                        already = any(abs(o["time"] - f) < 1 and tuple(o["entities"]) == key for o in outcomes)
                        if not already:
                            outcomes.append({
                                "time": float(f),
                                "kind": "collision",
                                "entities": [min(a, b), max(a, b)],
                                "value": None,
                                "src": []
                            })
                else:
                    if in_contact.get(key, False):
                        in_contact[key] = False

    # Exit detection
    B = 3.5
    for oid in active_oids:
        data = obj_data.get(oid, [])
        if len(data) < 2:
            continue
        last = data[-1]
        if last["f"] < entry_times.get(oid, 0) + 5:
            continue  # Not tracked enough
        if last["f"] >= t1 - 3:
            continue
        vx, vy = last["vx"], last["vy"]
        spd = math.sqrt(vx ** 2 + vy ** 2)
        if spd < 0.05:
            continue
        f0 = last["f"]
        x0, y0 = last["x"], last["y"]
        exit_f = None
        for f in range(f0 + 1, int(t1) + 20):
            x = x0 + vx * (f - f0)
            y = y0 + vy * (f - f0)
            if abs(x) > B or abs(y) > B:
                exit_f = f
                break
        if exit_f and exit_f > t0:
            outcomes.append({
                "time": float(exit_f),
                "kind": "object_exit",
                "entities": [oid],
                "value": None,
                "src": []
            })

    return sorted(outcomes, key=lambda o: (o["time"], o["kind"], tuple(o["entities"])))

