import math
from collections import defaultdict


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    obj_data = defaultdict(list)
    for node in scope_nodes(doc, scope):
        if "Motion log" in node["title"] and node["kind"] == "table":
            for _, rd in table_rows(node):
                try:
                    if rd.get("frame") and rd.get("object"):
                        f = int(float(rd["frame"]))
                        oid = rd["object"].split()[0]
                        obj_data[oid].append({
                            "f": f, "x": float(rd["x"]), "y": float(rd["y"]),
                            "vx": float(rd["vx"]), "vy": float(rd["vy"])
                        })
                except:
                    continue
            break

    for oid in obj_data:
        obj_data[oid].sort(key=lambda r: r["f"])

    # Objects from inputs
    active_oids = set()
    entry_times = {}
    obj_materials = {}
    for inp in inputs:
        for eid in inp["entities"]:
            active_oids.add(eid)
            entry_times[eid] = inp["time"]
            desc = inp["fields"].get("description", "")
            obj_materials[eid] = "metal" if "metal" in desc else "rubber"

    t0 = start if start is not None else 0.0
    t1 = horizon if horizon is not None else recorded_end(doc, scope)
    if t1 is None:
        t1 = 127.0

    def get_state(oid, f):
        data = obj_data.get(oid, [])
        if not data:
            return None
        if f <= data[0]["f"]:
            r = data[0]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt, r["vx"], r["vy"]
        if f >= data[-1]["f"]:
            r = data[-1]
            dt = f - r["f"]
            return r["x"] + r["vx"] * dt, r["y"] + r["vy"] * dt, r["vx"], r["vy"]
        for i in range(len(data) - 1):
            if data[i]["f"] <= f <= data[i + 1]["f"]:
                t = (f - data[i]["f"]) / (data[i + 1]["f"] - data[i]["f"])
                return (data[i]["x"] + t * (data[i + 1]["x"] - data[i]["x"]),
                        data[i]["y"] + t * (data[i + 1]["y"] - data[i]["y"]),
                        data[i]["vx"], data[i]["vy"])
        return None

    # Initialize state at t0 from motion data
    state = {}
    for oid in active_oids:
        s = get_state(oid, t0)
        if s is not None:
            state[oid] = {"x": s[0], "y": s[1], "vx": s[2], "vy": s[3], "active": True}
        elif oid in entry_times and entry_times[oid] < t0:
            state[oid] = {"x": 0, "y": 0, "vx": 0, "vy": 0, "active": True}

    # Physics constants
    CR = 0.45  # collision radius
    FRIC = 0.001  # per-frame friction

    outcomes = []
    in_contact = {}
    f_start = int(math.ceil(t0))
    f_end = int(math.floor(t1))

    for f in range(f_start, f_end + 1):
        # Update positions
        for oid, s in state.items():
            if s["active"]:
                s["x"] += s["vx"]
                s["y"] += s["vy"]
                s["vx"] *= (1 - FRIC)
                s["vy"] *= (1 - FRIC)

        # Check collisions
        oids = sorted(state.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                a, b = oids[i], oids[j]
                if not state[a]["active"] or not state[b]["active"]:
                    continue
                sa, sb = state[a], state[b]
                dx = sb["x"] - sa["x"]
                dy = sb["y"] - sa["y"]
                d = math.sqrt(dx * dx + dy * dy)
                key = (min(a, b), max(a, b))
                if d < CR:
                    if not in_contact.get(key, False):
                        in_contact[key] = True
                        # Check if approaching
                        dvn = (sa["vx"] - sb["vx"]) * dx + (sa["vy"] - sb["vy"]) * dy
                        if dvn > 0 or d < CR * 0.5:
                            # Elastic collision
                            nx, ny = dx / d, dy / d if d > 0.01 else (1, 0)
                            # Material-dependent restitution
                            ma = obj_materials.get(a, "rubber")
                            mb = obj_materials.get(b, "rubber")
                            if ma == mb == "rubber":
                                e = 0.05
                            elif ma == mb == "metal":
                                e = 0.9
                            else:
                                e = 0.5
                            dvn = (sa["vx"] - sb["vx"]) * nx + (sa["vy"] - sb["vy"]) * ny
                            if dvn > 0:
                                J = (1 + e) * dvn / 2
                                sa["vx"] -= J * nx
                                sa["vy"] -= J * ny
                                sb["vx"] += J * nx
                                sb["vy"] += J * ny
                            outcomes.append({
                                "time": float(f),
                                "kind": "collision",
                                "entities": [min(a, b), max(a, b)],
                                "value": None,
                                "src": []
                            })
                else:
                    if d > CR * 1.5:
                        in_contact[key] = False

    # Exit detection
    B = 3.0
    for oid, s in state.items():
        if not s["active"]:
            continue
        spd = math.sqrt(s["vx"] ** 2 + s["vy"] ** 2)
        if spd < 0.1:
            continue
        # Extrapolate
        x0, y0 = s["x"], s["y"]
        vx, vy = s["vx"], s["vy"]
        f0 = f_end
        exit_f = None
        for f in range(f0 + 1, int(t1) + 30):
            x = x0 + vx * (f - f0)
            y = y0 + vy * (f - f0)
            if abs(x) > B or abs(y) > B:
                exit_f = f
                break
        if exit_f and exit_f > t0:
            outcomes.append({
                "time": float(exit_f),
                "kind": "object_exit",
                "entities": [oid],
                "value": None,
                "src": []
            })

    return sorted(outcomes, key=lambda o: (o["time"], o["kind"], tuple(o["entities"])))
